--
-- Name: is_exempt_from_rls(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_exempt_from_rls() RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    RETURN (
        -- Permite usuários administradores do próprio Postgres / Supabase (migrations e admin do dashboard)
        current_user IN ('postgres', 'service_role', 'supabase_admin')
        OR
        -- Verifica se a variável de sessão do backend foi definida como 'super_admin'
        current_setting('app.current_user_role', true) = 'super_admin'
        OR
        -- Verifica se no token JWT do Supabase (caso use Supabase Auth) o role é super_admin
        (auth.jwt() ->> 'role') = 'super_admin'
    );
END;
$$;


